-- Production PostgreSQL. Read-only observations only. Do not replace with mutating RPC invocation.

BEGIN READ ONLY; SELECT jsonb_build_object('observed_at',now(),'pending_posts',(SELECT jsonb_agg(x) FROM (SELECT brand_id,post_type,status,scheduled_for,created_at,attempt_count,started_at FROM scheduled_posts WHERE brand_id IN ('kabumori','ai_salaryman_lab') AND status IN ('pending','running','processing') ORDER BY brand_id,scheduled_for)x),'runs',(SELECT jsonb_agg(x) FROM (SELECT 'news_monitor' AS kind,status,trigger_type,count(*) AS count,max(started_at) AS last_started_at FROM important_news_monitor_runs WHERE started_at>=now()-interval '72 hours' GROUP BY status,trigger_type UNION ALL SELECT 'news_shadow',status,trigger_type,count(*),max(started_at) FROM important_news_shadow_runs WHERE started_at>=now()-interval '72 hours' GROUP BY status,trigger_type UNION ALL SELECT 'news_discovery',status,trigger_type,count(*),max(started_at) FROM news_discovery_runs WHERE started_at>=now()-interval '72 hours' GROUP BY status,trigger_type)x),'settings',jsonb_build_object('news',(SELECT to_jsonb(t) FROM important_news_monitor_settings t),'consumer',(SELECT to_jsonb(t) FROM market_report_consumer_settings t),'broadcast',(SELECT to_jsonb(t)-'pilot_user_ids' FROM market_report_broadcast_settings t),'ondemand',(SELECT to_jsonb(t) FROM personalized_ondemand_settings t),'morning',(SELECT jsonb_agg(jsonb_build_object('brand_id',brand_id,'is_active',is_active,'updated_at',updated_at)) FROM morning_report_settings),'close',(SELECT jsonb_agg(jsonb_build_object('brand_id',brand_id,'is_active',is_active,'updated_at',updated_at)) FROM close_report_settings)),'analysis_jobs',(SELECT jsonb_agg(x) FROM (SELECT status,notify_status,count(*) AS count,max(requested_at) AS last_requested_at,max(updated_at) AS last_updated_at FROM personalized_analysis_jobs GROUP BY status,notify_status)x),'other_tables',(SELECT jsonb_agg(table_name) FROM information_schema.tables WHERE table_schema='public' AND table_name ~ '(market_report|personalized|intelligence|push|notification)')); COMMIT;

BEGIN READ ONLY; SELECT jsonb_build_object('observed_at',now(),'claim_definition',(SELECT prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='claim_due_post'),'post_0200',(SELECT jsonb_agg(x) FROM (SELECT brand_id,post_type,status,count(*) AS count,max(created_at) AS last_at FROM post_execution_logs WHERE created_at>='2026-10-17T02:00:00Z' GROUP BY brand_id,post_type,status ORDER BY brand_id,post_type,status)x),'new_posts_0200',(SELECT count(*) FROM scheduled_posts WHERE brand_id='kabumori' AND created_at>='2026-10-17T02:00:00Z'),'pending_kabumori',(SELECT jsonb_agg(x) FROM (SELECT post_type,status,scheduled_for,created_at,attempt_count FROM scheduled_posts WHERE brand_id='kabumori' AND status IN ('pending','running') ORDER BY scheduled_for)x),'news_after_0200',jsonb_build_object('created',(SELECT count(*) FROM important_news_candidates WHERE created_at>='2026-10-17T02:00:00Z'),'updated',(SELECT count(*) FROM important_news_candidates WHERE updated_at>='2026-10-17T02:00:00Z'),'runs',(SELECT count(*) FROM important_news_monitor_runs WHERE started_at>='2026-10-17T02:00:00Z')),'notifications_after_0200',(SELECT count(*) FROM notifications WHERE created_at>='2026-10-17T02:00:00Z'),'unsafe_notifications',(SELECT count(*) FROM notifications WHERE push_status IS DISTINCT FROM 'sent')); COMMIT;

BEGIN READ ONLY;
SELECT jsonb_build_object(
'observed_at',now(),'read_only',current_setting('transaction_read_only'),
'cron',(SELECT jsonb_agg(x) FROM (SELECT jobid,jobname,schedule,active,substring(command from 'functions/v1/([a-zA-Z0-9_-]+)') AS edge_function,md5(command) AS command_fingerprint FROM cron.job ORDER BY jobid)x),
'pending_posts',(SELECT jsonb_agg(x) FROM (SELECT brand_id,post_type,status,scheduled_for,created_at,attempt_count FROM scheduled_posts WHERE brand_id IN ('kabumori','ai_salaryman_lab') AND status IN ('pending','running') ORDER BY brand_id,scheduled_for)x),
'news_statuses',(SELECT jsonb_agg(x) FROM (SELECT status,count(*) AS count,max(created_at) AS last_created_at,max(updated_at) AS last_updated_at FROM important_news_candidates GROUP BY status ORDER BY status)x),
'notifications',(SELECT jsonb_agg(x) FROM (SELECT source_type,push_status,count(*) AS count,max(created_at) AS last_created_at FROM notifications GROUP BY source_type,push_status ORDER BY source_type,push_status)x),
'new_posts_since_0200',(SELECT count(*) FROM scheduled_posts WHERE brand_id='kabumori' AND created_at>='2026-10-17T02:00:00Z'),
'new_news_since_0200',(SELECT count(*) FROM important_news_candidates WHERE created_at>='2026-10-17T02:00:00Z'),
'updated_news_since_0200',(SELECT count(*) FROM important_news_candidates WHERE updated_at>='2026-10-17T02:00:00Z'),
'new_notifications_since_0200',(SELECT count(*) FROM notifications WHERE created_at>='2026-10-17T02:00:00Z'),
'active_news_runs',(SELECT count(*) FROM important_news_monitor_runs WHERE completed_at IS NULL AND status NOT IN ('failed','completed')),
'weekly_planner',(SELECT jsonb_build_object('md5',md5(p.prosrc),'references',jsonb_build_object('useful_tip_schedule_settings',p.prosrc LIKE '%useful_tip_schedule_settings%','is_active',p.prosrc LIKE '%is_active%','scheduled_posts',p.prosrc LIKE '%scheduled_posts%')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='plan_weekly_useful_tips'),
'useful_tip_settings',(SELECT jsonb_agg(to_jsonb(t)-'id') FROM useful_tip_schedule_settings t)
);
COMMIT;
